mapper.select:
SELECT p.id, p.author_id, p.content, p.image_urls, p.video_id, p.like_count, p.comment_count, p.share_count, p.created_at, u.nickname AS author_nickname, u.avatar_url AS author_avatar, u.signature AS author_signature, v.title AS video_title, v.cover_url AS video_cover, v.duration_seconds AS video_duration, EXISTS (SELECT 1 FROM video_reaction r WHERE r.user_id = #{viewerId} AND r.reaction_type = 3 AND r.video_id = p.video_id) AS liked FROM user_post p JOIN `user` u ON u.id = p.author_id AND u.deleted_at IS NULL LEFT JOIN video v ON v.id = p.video_id AND v.deleted_at IS NULL WHERE p.status = 1 AND p.deleted_at IS NULL AND (p.visibility = 0 OR p.author_id = #{viewerId})
AND p.author_id = #{targetUserId}
AND p.id < #{cursorId}
ORDER BY p.id DESC LIMIT #{limit}

SELECT u.id AS user_id, u.nickname, u.avatar_url, u.signature, u.level, f.created_at AS followed_at, CASE WHEN EXISTS (SELECT 1 FROM user_follow ff WHERE ff.follower_id = #{viewerId} AND ff.followee_id = u.id) THEN TRUE ELSE FALSE END AS followed FROM user_follow f JOIN `user` u ON u.id = f.follower_id f.followee_id AND u.deleted_at IS NULL WHERE 1 = 1
AND f.followee_id = #{otherId} AND f.follower_id = #{viewerId}
AND f.id < #{cursorId}
ORDER BY f.id DESC LIMIT #{limit}
